//! Independent exact rational gates, replacing the retired translated reference.
//! No expected value is generated by the implementation under test.
use soneflow::core::calc_slopes::{calc_slopes, calc_slopes_into, calc_slopes_n_only};
const FIXTURE: &[u8] = include_bytes!("fixtures/l4_owned/owned-oracle-270.bin");
const ROW_BYTES: usize = 503 * 8;
fn value(row: &[u8], i: usize) -> f64 {
    f64::from_le_bytes(row[i * 8..(i + 1) * 8].try_into().unwrap())
}
fn rows() -> impl Iterator<Item = &'static [u8]> {
    assert_eq!(&FIXTURE[..8], b"L4OWNV1\0");
    assert_eq!(u32::from_le_bytes(FIXTURE[8..12].try_into().unwrap()), 270);
    assert_eq!(FIXTURE.len(), 12 + 270 * ROW_BYTES);
    FIXTURE[12..]
        .as_chunks::<ROW_BYTES>()
        .0
        .iter()
        .map(|row| row.as_slice())
}
#[test]
fn independent_fraction_intervals_preserve_original_one_e_minus_twelve_gate() {
    for (frame, row) in rows().enumerate() {
        let core = std::array::from_fn(|band| value(row, band));
        let (total, specific) = calc_slopes(&core);
        for (point, got) in std::iter::once(total).chain(specific).enumerate() {
            let low = value(row, 21 + 2 * point);
            let high = value(row, 22 + 2 * point);
            assert!(
                got.is_finite() && got >= low && got <= high,
                "frame={frame} point={point} got={got} interval=[{low},{high}]"
            );
        }
    }
}
#[test]
fn complete_writes_repeatability_and_three_total_apis_remain_bitwise() {
    for row in rows() {
        let core = std::array::from_fn(|band| value(row, band));
        let (total, specific) = calc_slopes(&core);
        let mut output = [f64::NAN; 240];
        assert_eq!(
            calc_slopes_into(&core, &mut output).to_bits(),
            total.to_bits()
        );
        assert_eq!(calc_slopes_n_only(&core).to_bits(), total.to_bits());
        assert_eq!(output.map(f64::to_bits), specific.map(f64::to_bits));
        let repeated = calc_slopes(&core);
        assert_eq!(repeated.0.to_bits(), total.to_bits());
        assert_eq!(repeated.1.map(f64::to_bits), specific.map(f64::to_bits));
    }
}
#[test]
fn flat_core_has_analytic_area_including_frozen_edge_extension() {
    let extension = 0.0001_f32 as f64;
    for level in [0.0, 0.5, 1.0, 2.0, 16.0] {
        let (total, specific) = calc_slopes(&[level; 21]);
        let exact_as_float = level * (24.0 + extension);
        assert!((total - exact_as_float).abs() <= 1e-12 * exact_as_float.abs().max(1.0));
        assert!(specific.iter().all(|x| x.to_bits() == level.to_bits()));
    }
}
